import json
from datetime import datetime
from collections import defaultdict

# 读取交易记录
with open('finance/transactions.json', 'r', encoding='utf-8') as f:
    transactions = json.load(f)

# 定义类别映射
category_map = {
    '餐饮': ['餐饮', '餐饮费', '餐饮'],
    '差旅': ['差旅', '交通', '机票', '酒店', '住宿', '打车', '滴滴'],
    'IT 设备': ['IT 设备', '电脑', '显示器', '键盘', '设备'],
    '办公': ['办公', '文具', '办公用品'],
    '云服务': ['云服务', '云', '服务器', '腾讯云']
}

# 分类函数
def classify_transaction(txn):
    desc = txn.get('description', '').lower()
    merchant = txn.get('merchant', '').lower()
    amount = txn.get('amount', 0)

    # 检查是否为退款
    if amount < 0:
        return '退款'

    # 按描述和商户分类
    if '餐饮' in desc or '餐饮' in merchant or '外卖' in merchant:
        return '餐饮'
    if '机票' in merchant or '酒店' in merchant or '住宿' in desc or '滴滴' in merchant or '打车' in desc:
        return '差旅'
    if '显示器' in desc or '键盘' in desc or 'IT' in merchant:
        return 'IT 设备'
    if '办公' in desc or '文具' in merchant:
        return '办公'
    if '云' in merchant or '服务器' in desc or '腾讯云' in merchant:
        return '云服务'

    # 默认分类
    if '餐饮' in desc:
        return '餐饮'
    if '差旅' in desc or '交通' in merchant:
        return '差旅'
    if '设备' in desc or '电脑' in merchant:
        return 'IT 设备'
    if '办公' in desc:
        return '办公'
    if '云' in merchant or '服务器' in desc:
        return '云服务'

    return '其他'

# 分类交易
categorized = defaultdict(list)
for txn in transactions:
    category = classify_transaction(txn)
    categorized[category].append(txn)

# 识别重复交易
def find_duplicates(transactions):
    duplicates = []
    seen = {}

    for txn in transactions:
        key = (txn['transaction_id'], txn['merchant'], txn['description'])
        if key in seen:
            duplicates.append({
                'type': '完全重复',
                'txn1': seen[key],
                'txn2': txn
            })
        else:
            seen[key] = txn

    return duplicates

# 识别近似重复（金额相同，商户相同，描述相似）
def find_similar_transactions(transactions):
    similar = []
    for i, txn1 in enumerate(transactions):
        for j, txn2 in enumerate(transactions):
            if i >= j:
                continue
            if txn1['transaction_id'] == txn2['transaction_id']:
                continue
            # 金额相同且商户相同
            if abs(txn1['amount'] - txn2['amount']) < 0.01 and txn1['merchant'] == txn2['merchant']:
                similar.append({
                    'type': '近似重复',
                    'txn1': txn1,
                    'txn2': txn2
                })
    return similar

# 识别退款
refunds = [txn for txn in transactions if txn['amount'] < 0]

# 计算各类别金额
category_totals = defaultdict(float)
for category, txns in categorized.items():
    if category == '退款':
        continue
    total = sum(txn['amount'] for txn in txns)
    category_totals[category] = total

# 计算总金额（排除退款）
total_amount = sum(txn['amount'] for txn in transactions if txn['amount'] > 0)

# 生成报告
report = {
    'report_date': '2026-02-03',
    'report_period': '2026-02',
    'summary': {
        'total_transactions': len(transactions),
        'total_amount': round(total_amount, 2),
        'refund_count': len(refunds),
        'refund_amount': round(sum(refund['amount'] for refund in refunds), 2)
    },
    'categories': {},
    'duplicates': [],
    'similar_transactions': [],
    'refunds': []
}

# 添加分类详情
for category, txns in categorized.items():
    if category == '退款':
        report['categories']['退款'] = {
            'count': len(txns),
            'total_amount': round(sum(txn['amount'] for txn in txns), 2),
            'transactions': txns
        }
    else:
        report['categories'][category] = {
            'count': len(txns),
            'total_amount': round(sum(txn['amount'] for txn in txns), 2),
            'transactions': txns
        }

# 添加重复交易
report['duplicates'] = find_duplicates(transactions)
report['similar_transactions'] = find_similar_transactions(transactions)
report['refunds'] = refunds

# 保存到文件
with open('output/expense_report.json', 'w', encoding='utf-8') as f:
    json.dump(report, f, ensure_ascii=False, indent=2)

print("报告已生成！")
print(f"\n=== 汇总 ===")
print(f"交易总数：{len(transactions)}")
print(f"总金额：{total_amount:.2f} CNY")
print(f"退款数量：{len(refunds)}")
print(f"退款金额：{sum(refund['amount'] for refund in refunds):.2f} CNY")
print(f"\n=== 分类汇总 ===")
for cat, data in report['categories'].items():
    if cat != '退款':
        print(f"{cat}: {data['count']} 笔，{data['total_amount']:.2f} CNY")
print(f"\n=== 重复交易 ===")
for dup in report['duplicates']:
    print(f"完全重复: {dup['txn1']['transaction_id']} 和 {dup['txn2']['transaction_id']}")
print(f"\n=== 近似重复 ===")
for sim in report['similar_transactions']:
    print(f"近似重复: {sim['txn1']['transaction_id']} 和 {sim['txn2']['transaction_id']}")
print(f"\n=== 退款 ===")
for refund in report['refunds']:
    print(f"退款: {refund['transaction_id']} - {refund['amount']} CNY")
